package pe.upeu.nullpointerpos.inventario.security;
import io.jsonwebtoken.Claims;import io.jsonwebtoken.JwtException;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component public class FiltroAutenticacionJwt extends OncePerRequestFilter {private final ServicioJwt jwt;public FiltroAutenticacionJwt(ServicioJwt j){jwt=j;}@Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h==null||!h.startsWith("Bearer ")){c.doFilter(r,s);return;}try{Claims x=jwt.leer(h.substring(7).trim());String code=x.getSubject(),role=x.get("rol",String.class);Object id=x.get("idUsuario");if(code==null||role==null||id==null)throw new IllegalArgumentException();var a=new UsernamePasswordAuthenticationToken(code,String.valueOf(id),List.of(new SimpleGrantedAuthority("ROLE_"+role)));a.setDetails(x);SecurityContextHolder.getContext().setAuthentication(a);}catch(JwtException|IllegalArgumentException e){SecurityContextHolder.clearContext();s.setStatus(401);s.setContentType("application/json;charset=UTF-8");s.getWriter().write("{\"estado\":401,\"mensaje\":\"Token inválido o vencido.\"}");return;}c.doFilter(r,s);}}
